#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn example() {
        let mut t = PrefixTree::new();
        t.insert("card");
        t.insert("care");
        assert!(!t.contains("car"));
        assert!(t.has_prefix("car"));
        assert_eq!(t.count_prefix("car"), 2);
    }

    #[test]
    fn exact_word() {
        let mut t = PrefixTree::new();
        t.insert("car");
        t.insert("card");
        assert!(t.contains("car"));
        assert!(t.contains("card"));
        assert!(!t.contains("ca"));
    }

    #[test]
    fn missing_prefix() {
        let mut t = PrefixTree::new();
        t.insert("apple");
        assert!(!t.has_prefix("apx"));
        assert_eq!(t.count_prefix("b"), 0);
        assert!(!t.contains("applesauce"));
    }

    #[test]
    fn duplicates_and_empty_prefix() {
        let mut t = PrefixTree::new();
        for w in ["a", "ab", "ab", "abc", "b"] {
            t.insert(w);
        }
        assert_eq!(t.count_prefix(""), 4);
        assert_eq!(t.count_prefix("ab"), 2);
        assert!(t.has_prefix(""));
    }

    #[test]
    fn many_words() {
        let mut t = PrefixTree::new();
        for i in 0..3000 {
            t.insert(&format!("w{}", i));
        }
        assert_eq!(t.count_prefix("w1"), 1111);
        assert!(t.contains("w2999"));
    }
}
